/* attachment tray */
.at{padding:12px}
.at-drop{padding:10px;transition:background .3s}
.at-drop::before{transition:opacity .3s}
.at-drop.over::before{opacity:1}
.at-in{display:flex;flex-direction:column;align-items:center;gap:6px;padding:20px 12px;border:1px dashed var(--icon-line);background:var(--panel);text-align:center}
.at-drop.over .at-in{border-color:var(--accent)}
.at-in .t{font-weight:600;font-size:14px}
.at-link{color:var(--accent);font:inherit;text-transform:inherit;border-bottom:1px solid var(--accent-icon-line)}
.at-file{display:grid;grid-template-columns:38px 1fr auto 22px;align-items:center;gap:10px;padding:10px 4px 4px}
.at-file .kbd{justify-content:center}
.at-file .nm{font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.at-file .sz{font-size:10px}
.at-prog{grid-column:2/4;height:2px;background:var(--line);position:relative;overflow:hidden;margin-bottom:6px}
.at-prog i{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--accent);transition:width .2s linear}
.at-file.ok .at-prog i{background:var(--success)}
.at-x{color:var(--muted);transition:color .2s}
.at-x:hover{color:var(--danger)}

/* ---------- attachment tray ---------- */
{
  const drop = $('#at-drop'), list = $('#at-list');
  const ext = n => { const e = (n.split('.').pop() || '').toUpperCase(); return e.length > 4 ? 'FILE' : e || 'FILE'; };
  const size = b => b > 1e6 ? (b / 1e6).toFixed(1) + ' MB' : Math.max(1, Math.round(b / 1e3)) + ' KB';
  function addFile(name, sz){
    const w = document.createElement('div');
    w.innerHTML = `<div class="uf"><div class="at-file"><span class="kbd">${ext(name).replace(/[<>&"]/g,'')}</span><span class="nm"></span><span class="mono-xs sz">${sz}</span><button class="at-x" aria-label="Remove file">${ic('close','sm')}</button><div class="at-prog"><i></i></div></div></div>`;
    w.querySelector('.nm').textContent = name;
    list.appendChild(w); unfoldIn(w);
    const bar = w.querySelector('.at-prog i'), row = w.querySelector('.at-file'); let p = 0; const sp = 2 + Math.random() * 4;
    const t = setInterval(() => { p = Math.min(100, p + sp); bar.style.width = p + '%'; if (p >= 100){ clearInterval(t); row.classList.add('ok'); ambient('c30', 'pop'); } }, 60);
    w.querySelector('.at-x').addEventListener('click', () => { clearInterval(t); Sound.play('tick'); w.classList.remove('open'); setTimeout(() => w.remove(), 500); });
  }
  $('#at-sample').addEventListener('click', e => { e.stopPropagation(); Sound.play('tab'); [['Brand guidelines.fig','4.2 MB'],['Research summary.pdf','1.1 MB'],['Hero shot.png','860 KB']].forEach((f, i) => setTimeout(() => addFile(f[0], f[1]), i * 220)); });
  ['dragenter','dragover'].forEach(ev => drop.addEventListener(ev, e => { e.preventDefault(); drop.classList.add('over'); }));
  ['dragleave','drop'].forEach(ev => drop.addEventListener(ev, e => { e.preventDefault(); drop.classList.remove('over'); }));
  drop.addEventListener('drop', e => { const fs = Array.from((e.dataTransfer && e.dataTransfer.files) || []); if (fs.length) Sound.play('select'); fs.slice(0, 6).forEach((f, i) => setTimeout(() => addFile(f.name, size(f.size)), i * 200)); });
}
